CREATE TABLE cas_documents(id BIGINT PRIMARY KEY,body TEXT NOT NULL,version BIGINT NOT NULL); CREATE TABLE cas_history(document_id BIGINT NOT NULL,version BIGINT NOT NULL,body TEXT NOT NULL,PRIMARY KEY(document_id,version),FOREIGN KEY(document_id) REFERENCES cas_documents(id)); INSERT INTO cas_documents VALUES(31,'draft',0);
DELIMITER $$
CREATE TRIGGER reject_cas_history BEFORE INSERT ON cas_history FOR EACH ROW BEGIN IF NEW.body='blocked' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='fixture backend failure'; END IF; END$$
DELIMITER ;

CREATE TABLE slot_catalog(id BIGINT PRIMARY KEY,enabled INT NOT NULL); CREATE TABLE slot_placements(user_id BIGINT PRIMARY KEY,slot_id BIGINT NOT NULL UNIQUE,FOREIGN KEY(slot_id) REFERENCES slot_catalog(id)); INSERT INTO slot_catalog VALUES(1,1),(2,1),(3,0),(4,1),(5,1); INSERT INTO slot_placements VALUES(501,1),(502,2);
DELIMITER $$
CREATE TRIGGER reject_slot_update BEFORE UPDATE ON slot_placements FOR EACH ROW BEGIN IF NEW.slot_id=5 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='fixture backend failure'; END IF; END$$
DELIMITER ;

CREATE TABLE roster_teams(id BIGINT PRIMARY KEY,revision BIGINT NOT NULL); CREATE TABLE roster_members(team_id BIGINT NOT NULL,member_id BIGINT NOT NULL,role VARCHAR(128) NOT NULL,PRIMARY KEY(team_id,member_id),FOREIGN KEY(team_id) REFERENCES roster_teams(id)); INSERT INTO roster_teams VALUES(42,7); INSERT INTO roster_members VALUES(42,700,'admin');
DELIMITER $$
CREATE TRIGGER reject_roster_member BEFORE INSERT ON roster_members FOR EACH ROW BEGIN IF NEW.member_id=999 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='fixture backend failure'; END IF; END$$
DELIMITER ;
